package profile

import (
	_ "embed"
	"strings"
	"sync"
)

// Every slug the web sprite can render; regenerated by scripts/sync-lucide-icons.mjs.
//
//go:embed lucide_icons.gen.txt
var lucideIconData string

var lucideIcons = sync.OnceValue(func() map[string]struct{} {
	return parseIconCatalog(lucideIconData)
})

func parseIconCatalog(data string) map[string]struct{} {
	set := make(map[string]struct{}, 1800)
	for slug := range strings.SplitSeq(strings.TrimSpace(data), "\n") {
		slug = strings.TrimSuffix(slug, "\r")
		set[slug] = struct{}{}
	}
	return set
}

func isCatalogIcon(slug string) bool {
	_, found := lucideIcons()[slug]
	return found
}

// Remove in v0.5.0 after migrating persisted pre-1.61 Lucide names.
func canonicalIcon(slug string) string {
	switch slug {
	case "album":
		return "square-bookmark"
	case "book-marked":
		return "book-bookmark"
	case "building-2":
		return "building-complex"
	case "flip-horizontal-2":
		return "triangles-centerline-dashed-horizontal"
	case "flip-vertical-2":
		return "triangles-centerline-dashed-vertical"
	case "music":
		return "eighth-notes"
	case "music-2":
		return "eighth-note"
	case "music-3":
		return "half-note"
	case "music-4":
		return "sixteenth-notes"
	case "trash-2":
		return "trash"
	default:
		return slug
	}
}
